#!/bin/sh
set -eu
umask 077
python3 -I -B - <<'INSTALL_CONT_R29'
import base64,hashlib,os,platform,zlib
from pathlib import Path
assert os.geteuid()==0 and platform.system()=='Linux'
raw=zlib.decompress(base64.b64decode('',validate=True))
assert len(raw)==5559 and hashlib.sha256(raw).hexdigest()=='be1f609c516943f20179e2b83901e1245256cd1e5cd1bf786f2b9d95635b1ec2'
p=Path('/root/t44-r9/continue-resource-r29-01.py');assert p.parent.resolve()==p.parent
fd=os.open(p,os.O_WRONLY|os.O_CREAT|os.O_EXCL|os.O_NOFOLLOW,0o444)
with os.fdopen(fd,'wb') as f:f.write(raw);f.flush();os.fsync(f.fileno())
print('R29_RESOURCE_CONTINUATION_INSTALLED_ONLY')
INSTALL_CONT_R29
